INSERT INTO public.checklist_secoes (id, modelo_versao_id, secao_key, titulo, ordem) VALUES
  ('51c2b674-b601-5594-b64a-f7f51c108b13', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'controle-saude', 'Controle de Saúde dos Funcionários', 1),
  ('4bb35495-624b-58a5-a08d-350d5fae6289', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'higiene-seguranca', 'Higiene e Segurança dos Funcionários', 2),
  ('141a3429-12c2-506f-a65f-262cf97f4c9b', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'responsabilidade-capacitacao', 'Responsabilidade Técnica, Capacitação e Visitantes', 3),
  ('f6d45d42-563d-5c73-938b-6a2bb38e1443', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'recebimento', 'Recebimento e Controle de Mercadorias', 4),
  ('06c9d0ef-a1ff-59f6-bdd7-dc77d22503a3', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'armazenamento', 'Armazenamento de Produtos', 5),
  ('ca000a84-c1fe-5317-8847-73c4c0972511', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'pre-preparo-preparo', 'Pré-preparo e Preparo dos Alimentos', 6),
  ('b22ad218-488e-5684-9c53-0933c9726f73', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'distribuicao-exposicao', 'Distribuição, Exposição para Venda e Consumo', 7),
  ('1389a76d-a7f0-5c88-a33b-d015b5a67975', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'granel', 'Comércio de Produtos de Origem Vegetal a Granel', 8),
  ('d05cd122-b8d6-5947-a49d-002bf7660787', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'guarda-amostras', 'Guarda de Amostras', 9),
  ('4d26e875-7c3f-5cf3-9b9c-cd6c6a559750', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'surto-dtha', 'Surto de DTHA', 10),
  ('19115dd6-46f9-5479-aac8-10c0393f88e0', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'transporte', 'Transporte de Alimentos', 11),
  ('1041bccd-f38a-535b-b5b6-f194ba468a6f', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'delivery', 'Entrega de Alimentos em Domicílio', 12),
  ('82c69530-9950-53c0-88d8-ef78f64dccca', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'higienizacao-instalacoes', 'Higienização das Instalações e do Ambiente', 13),
  ('a7ae936e-bef5-5d7b-b2b8-044acfdfa49e', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'agua', 'Abastecimento de Água', 14),
  ('dc4b3b62-7816-54eb-b379-d8cd33a52e35', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'esgoto-residuos-gas', 'Esgotamento Sanitário, Resíduos e Gás', 15),
  ('825fa3c5-4c42-52d5-8a4d-1df1844c8aa9', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'pragas', 'Controle Integrado de Vetores e Pragas Urbanas', 16),
  ('7830233b-c779-5cb6-b02d-ef0dba3fcbad', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'edificacoes-instalacoes', 'Edificações e Instalações', 17),
  ('4454f4ad-a839-54d6-ae5e-08afc5bdfdf4', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'vestiarios-sanitarios', 'Vestiários e Instalações Sanitárias dos Funcionários', 18),
  ('14a96eca-53de-5e80-a6b1-9c6080f32dfa', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'manual-bp-pop', 'Manual de Boas Práticas e POP', 19)
INSERT INTO public.checklist_itens (id, modelo_versao_id, secao_id, item_key, texto, critico, ordem) VALUES
  ('86475a1b-01a3-586d-ae6b-8ec65003e110', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '51c2b674-b601-5594-b64a-f7f51c108b13', '1.1', 'Controle de saúde dos manipuladores segue as diretrizes do PCMSO e da norma regulamentadora vigente.', false, 1),
  ('3b647943-583f-5c03-8ba7-2746d076fb3e', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '51c2b674-b601-5594-b64a-f7f51c108b13', '1.1b', 'São realizados exames laboratoriais de coprocultura e parasitológico na admissão e no acompanhamento periódico de todos os manipuladores.', false, 2),
  ('873633f7-26ad-5e1a-831d-050a76c58947', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '51c2b674-b601-5594-b64a-f7f51c108b13', '1.2', 'Exames de coprocultura e parasitológico realizados anualmente para manipuladores diretos, para quem distribui/oferta refeições e para os envolvidos em atividades com alimentos totalmente embalados.', false, 3),
  ('5fa2579f-adac-5937-95d5-ab8e542cef6b', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '51c2b674-b601-5594-b64a-f7f51c108b13', '1.3', 'Atestados de saúde (ou cópias), com indicação dos exames laboratoriais, disponíveis para consulta.', false, 4),
  ('2c06f564-c0d0-5d4c-85e4-9f2f6a376e58', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '51c2b674-b601-5594-b64a-f7f51c108b13', '1.4', 'Manipuladores com sinais/sintomas de doenças infecciosas, lesões de pele/mucosas/unhas ou feridas nas mãos/braços afastados da manipulação enquanto persistirem essas condições.', true, 5),
  ('70d92289-8b8b-529a-a992-74c12e4421ca', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.1', 'Funcionários que manipulam alimentos apresentam barba/bigode raspados, unhas curtas/limpas sem esmalte/base, sem maquiagem e sem adornos (colares, pulseiras, brincos, piercings, relógios, anéis) (quando a função não se restringe a transporte/recebimento/reposição de embalados).', false, 6),
  ('a21ea0ae-1eca-5e50-b22e-1101dc474c8e', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.1b', 'Objetos pessoais de uso no trabalho são guardados nos bolsos inferiores do uniforme (mesma exceção do item anterior).', false, 7),
  ('3f3e852f-2dcb-53d5-83e6-fabb4c1ba88d', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.2', 'Uniformes bem conservados, limpos, com troca diária, usados só nas dependências internas.', false, 8),
  ('c8c3663d-8d0f-501d-ac21-ede7957519f5', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.2b', 'Calçados fechados, antiderrapantes e em boas condições.', false, 9),
  ('f0846d0e-8a28-54a9-a4fa-d489054732ab', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.2c', 'Cabelos mantidos presos e totalmente protegidos com redes/toucas.', false, 10),
  ('4f78fc2d-8b38-584d-a687-b6d87977d20a', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.3', 'Empresa disponibiliza EPI limpo, em bom estado, em quantidade suficiente.', false, 11),
  ('558b3d3b-0663-533b-b046-58c2f680cd22', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.3b', 'Uso obrigatório de EPI (blusa, capa térmica, luvas, botas impermeáveis) em câmaras frias (quando existente câmara fria).', false, 12),
  ('acd95f13-e97f-528d-b242-00cbf104ca55', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.3c', 'Uso de EPI (avental, luvas, botas impermeáveis) na higienização, sem panos/sacos plásticos para proteção do uniforme.', false, 13),
  ('7aafa7ad-90fc-5722-88f8-57b271296266', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.3d', 'Vedação de materiais termossensíveis perto de calor e de botas com água fervente respeitada.', false, 14),
  ('601ff978-278e-54b8-9daf-6e25c350573f', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.3e', 'Luva de borracha de cano longo usada na manipulação de saneantes, higienizada/armazenada após o uso.', false, 15),
  ('cbf2be1c-1009-557b-818a-ce8567975c04', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.4', 'Manipuladores realizam antissepsia das mãos com frequência adequada, inclusive antes de utensílios higienizados ou luvas descartáveis.', true, 16),
  ('1c6aa6c8-457a-54d7-945b-229ce17c3643', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.4b', 'Vedação de luvas descartáveis em processos com calor/moagem/trituração/mistura respeitada.', false, 17),
  ('c7787ea2-a518-5f5f-9fc0-1d9e0863e502', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.4c', 'Luvas de malha de aço usadas no corte de carnes, higienizadas/armazenadas após o uso (quando há corte de carnes).', false, 18),
  ('0472fc97-299a-5343-a561-cfb7f4e244d4', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.4d', 'Máscaras, quando usadas, são descartáveis com critério/frequência de troca documentados (quando usa máscaras).', false, 19),
  ('53fbd3b7-24ec-561c-a956-7a212f694884', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.5', 'Manipuladores respeitam a vedação de cuspir, tossir ou espirrar sobre alimentos/superfícies, mascar ou comer durante a manipulação.', true, 20),
  ('95650825-d922-5495-afd5-3e51e1dc3c25', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.5b', 'Vedação das demais condutas do artigo durante a manipulação respeitada (falar desnecessariamente, cantar, assobiar, tocar corpo/cabelo, fumar, manipular dinheiro, usar celular, entre outras).', false, 21),
  ('5b9b6e81-64e8-5028-9e98-c4861db4b893', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.6', 'Funcionários higienizam as mãos nos momentos especificados (chegada, sanitário, tossir/espirrar, tocar corpo/cabelo, panos de limpeza, fumar, resíduos, dinheiro/cartões/eletrônicos, sacarias/caixas/sapatos, alimentos crus, reinício do serviço).', true, 22),
  ('5e7ac2b7-1d95-5813-a7cf-09afc308feb5', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.7', 'Cartazes com instruções ilustradas de higienização das mãos afixados nas pias exclusivas, inclusive sanitários/vestiários.', false, 23),
  ('a4df2cc0-c7d8-5682-bbc6-f841ce8f5931', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.7b', 'Procedimento de lavagem das mãos segue as etapas descritas (umedecer, lavar por no mínimo 40 segundos, enxaguar, secar com papel-toalha descartável, antissepsia adicional se o sabonete não for antisséptico).', true, 24),
  ('40282d8c-d3a9-5777-98c9-d16bb9db8fb1', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.7c', 'Coletor de papel com abertura sem contato manual próximo ao lavatório.', false, 25),
  ('c2ced9fe-10b2-548e-8250-9a3a7e0756fd', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '4bb35495-624b-58a5-a08d-350d5fae6289', '2.7d', 'Produtos antissépticos usados são aprovados pela Anvisa para antissepsia de mãos.', false, 26),
  ('32929b83-5716-5f26-aa67-c5fa5e78c61d', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '141a3429-12c2-506f-a65f-262cf97f4c9b', '3.1', 'Estabelecimento possui Responsável Técnico quando exigido pela legislação de licenciamento aplicável (verificar a legislação de licenciamento específica do tipo de estabelecimento antes de aplicar N/A entre este item e o 3.2 — a CVS 3/2026 não define, por si só, essa obrigatoriedade).', false, 27),
  ('9f7f2353-b531-52d1-a494-03fb908f263f', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '141a3429-12c2-506f-a65f-262cf97f4c9b', '3.2', 'Quando não há exigência de RT, a responsabilidade pelas Boas Práticas está formalmente a cargo do proprietário ou de funcionário capacitado que acompanha integralmente o processo (mesma verificação do item 3.1).', false, 28),
  ('0d601726-26e6-5cc1-a4c5-0403b74c06dc', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '141a3429-12c2-506f-a65f-262cf97f4c9b', '3.3', 'Programa de educação permanente em Boas Práticas, com registro nominal de participação.', false, 29),
  ('7fab08a8-ebfd-5cf8-bd80-68a0965b1a37', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '141a3429-12c2-506f-a65f-262cf97f4c9b', '3.4', 'Todos os manipuladores comprovam curso de Boas Práticas com carga horária mínima de 8 horas, cobrindo DTHA, higiene/saúde, qualidade da água/pragas, qualidade sanitária e POPs de higienização.', false, 30),
  ('4a602b29-a7c1-5869-b1d1-b2598bea24f7', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '141a3429-12c2-506f-a65f-262cf97f4c9b', '3.5', 'RT/funcionário capacitado tem autoridade para atualizar manual/POPs, acompanhar inspeções e notificar surtos de DTHA.', false, 31),
  ('e9910202-54d7-5b65-b390-4470439ef360', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '141a3429-12c2-506f-a65f-262cf97f4c9b', '3.6', 'Visitantes são instruídos sobre Boas Práticas e cumprem os requisitos de higiene/saúde exigidos dos funcionários.', false, 32),
  ('6921151e-767a-53b8-961e-15374c9feb42', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '141a3429-12c2-506f-a65f-262cf97f4c9b', '3.6b', 'Visitantes que supervisionam/fiscalizam ou executam manutenção estão identificados e paramentados (protetores de cabelo/barba, EPI) quando a atividade exigir.', false, 33),
  ('b0a6edae-0ec6-5b95-89d4-abd77a52bdbf', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.1', 'Critérios definidos para avaliação/seleção de fornecedores, incluindo licenciamento sanitário/registro no órgão competente.', false, 34),
  ('2389d98b-5a06-5b75-9aa6-2b401b8cfa84', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.2', 'Entregadores/veículos se apresentam em condições de higiene, e o recebimento ocorre em área protegida (chuva/sol/poeira, sem materiais inservíveis).', false, 35),
  ('d14b1891-58da-59ce-b845-8c538e2c8c37', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.3', 'Embalagens de matérias-primas/industrializados/prontos estão limpas e íntegras no recebimento.', false, 36),
  ('da7ed989-b28b-547c-b041-e10431748070', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.4', 'No recebimento são feitas avaliações quantitativa/qualitativa/sensorial (cor, aparência, odor, textura) e conferida a validade.', false, 37),
  ('57a6aec0-09ab-5a67-8e8e-f72e28e1c0fe', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.5', 'Produtos congelados recebidos não apresentam indícios de descongelamento/recongelamento.', true, 38),
  ('31af422d-a173-5b86-b554-4bc34e2300e9', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.6', 'Temperaturas de recebimento conferidas/registradas: congelados ≤ -12°C; pescados refrigerados 2-3°C; pescados/carnes cruas 0-5°C; carnes/derivados 4-7°C; demais produtos 4-10°C; aquecidos acima de 60°C.', true, 39),
  ('ed19331e-4531-53e3-8ceb-3974e7308a35', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.7', 'Produtos fora dos critérios devolvidos ao fornecedor ou segregados em local reservado/identificado.', false, 40),
  ('3bab375f-24a1-5b14-8051-95f41e0170a7', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', 'f6d45d42-563d-5c73-938b-6a2bb38e1443', '4.8', 'Mercadorias não ficam dispostas no piso, permanecem na recepção só o tempo necessário à avaliação, sem permanência em pátios/plataformas.', false, 41),
  ('44e329fc-134a-560f-96dc-d29316c0456d', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '06c9d0ef-a1ff-59f6-bdd7-dc77d22503a3', '5.1', 'Local com dimensão compatível ao volume, totalmente isolado do ambiente externo.', false, 42),
  ('0a0c6d56-fbb4-5c1f-92ba-2d8b77855d7e', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '06c9d0ef-a1ff-59f6-bdd7-dc77d22503a3', '5.1b', 'Ambiente limpo, livre de entulho/tóxico, ventilado, organizado, temperatura monitorada e registrada.', false, 43),
  ('72675651-17e0-554c-84f4-4745a637dce8', '25ad123a-de57-5aa9-b984-a26fbad5d2c7', '06c9d0ef-a1ff-59f6-bdd7-dc77d22503a3', '5.1c', 'Produtos protegidos de luz solar direta, conforme fabricante.', false, 44),
